CABECALHO = """-- ATHOSlife — 13 receitas salgadas da Cozinha (12/11/2026, segundo lote)
--
-- Pedido do dono depois do primeiro lote: mais 13, com foco em salgados.
-- Mesmas categorias de hoje, texto em pt/en/es/fr/hi, macros aproximados
-- (TACO) POR PORÇÃO, `ordem` 38–50. Pode rodar de novo: só insere a receita
-- que ainda não existe com aquele título.
-- Gerado por scripts/receitas/receitas_salgadas_2026_11_12.py.
"""

def sql(ordem=38):
    out = [CABECALHO]
    for r in R:
        pt = r['pt']
        trad = {l: {'titulo': r[l]['titulo'], 'subtitulo': r[l]['sub']} for l in ('en', 'es', 'fr', 'hi')}
        ctrad = {l: conteudo(l, r['porcoes'], r[l]) for l in ('en', 'es', 'fr', 'hi')}
        alerg = 'array[' + ','.join(q(a) for a in r['alerg']) + ']::text[]'
        out.append(f"""insert into public.receitas_cozinha
  (titulo, subtitulo, categoria, macros, kcal, tempo_preparo_min, cor_tema, premium, destaque, conteudo, ordem, alergenos, temas, tipo_prato, mascote_modo, traducoes, conteudo_traducoes)
select {q(pt['titulo'])}, {q(pt['sub'])}, {q(r['cat'])},
  {q(json.dumps({'proteina': r['p'], 'carboidrato': r['c'], 'gordura': r['g']}))}::jsonb, {r['kcal']}, {r['tempo']}, {q(COR[r['cat']])}, {str(r['premium']).lower()}, {str(r['destaque']).lower()},
  {q(conteudo('pt', r['porcoes'], pt))},
  {ordem}, {alerg}, '{{}}'::text[], {q(r['tipo'])}, 'chef',
  {q(json.dumps(trad, ensure_ascii=False))}::jsonb,
  {q(json.dumps(ctrad, ensure_ascii=False))}::jsonb
where not exists (select 1 from public.receitas_cozinha where titulo = {q(pt['titulo'])});
""")
        ordem += 1
    return '\n'.join(out)

if __name__ == '__main__':
    if len(sys.argv) > 1 and sys.argv[1] == 'titulos':
        for r in R:
            print(r['pt']['titulo'])
    else:
        sys.stdout.write(sql())
